5:/** Convert source to positioned tokens without repeatedly slicing its suffix. */
6:function tokenize(source) {
7:  const tokens = [];
8:  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
9:  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
10:  let offset = 0;
11:  while (offset < source.length) {
12:    const column = offset + 1;
13:    while (offset < source.length && /\s/.test(source[offset])) offset += 1;
14:    if (offset === source.length) break;
15:    number.lastIndex = offset;
16:    const numeric = number.exec(source);
17:    if (numeric) {
18:      tokens.push({ type: 'number', value: Number(numeric[0]), column });
19:      offset = number.lastIndex;
20:      continue;
21:    }
22:    identifier.lastIndex = offset;
23:    const name = identifier.exec(source);
24:    if (name) {
25:      tokens.push({ type: 'identifier', value: name[0], column });
26:      offset = identifier.lastIndex;
27:      continue;
28:    }
29:    const pair = source.slice(offset, offset + 2);
30:    if (['**', '//', '<=', '>=', '==', '!='].includes(pair)) {
31:      tokens.push({ type: 'operator', value: pair, column });
32:      offset += 2;
33:    } else if ('+-*/%<>() ,'.includes(source[offset]) && source[offset] !== ' ') {
34:      tokens.push({ type: 'operator', value: source[offset], column });
35:      offset += 1;
36:    } else {
37:      throw new ExprError('Unexpected character', column);
38:    }
39:  }
40:  tokens.push({ type: 'eof', value: '', column: source.length + 1 });
41:  return tokens;
42:}
43:
44:module.exports = { tokenize };

