37:/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
38:function evaluateAst(root, variables) {
39:  const frames = [{ node: root, phase: 0 }];
40:  let result;
41:  while (frames.length) {
42:    const frame = frames[frames.length - 1];
43:    const node = frame.node;
44:    if (node.type === 'number') {
45:      result = node.value;
46:      frames.pop();
47:    } else if (node.type === 'variable') {
48:      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
49:        throw new ExprError('Unknown variable', node.column);
50:      }
51:      result = variables[node.name];
52:      frames.pop();
53:    } else if (node.type === 'unary') {
54:      if (frame.phase === 0) {
55:        frame.phase = 1;
56:        frames.push({ node: node.operand, phase: 0 });
57:      } else {
58:        result = node.operator.value === '-' ? -Number(result) : Number(result);
59:        frames.pop();
60:      }
61:    } else if (node.type === 'binary') {
62:      if (frame.phase === 0) {
63:        frame.phase = 1;
64:        frames.push({ node: node.left, phase: 0 });
65:      } else if (frame.phase === 1) {
66:        frame.left = result;
67:        frame.phase = 2;
68:        frames.push({ node: node.right, phase: 0 });
69:      } else {
70:        result = apply(node.operator, frame.left, result);
71:        frames.pop();
72:      }
73:    } else if (node.type === 'comparison') {
74:      if (frame.phase === 0) {
75:        frame.phase = 1;
76:        frames.push({ node: node.operands[0], phase: 0 });
77:      } else if (frame.phase === 1) {
78:        frame.left = result;
79:        frame.index = 0;
80:        frame.phase = 2;
81:        frames.push({ node: node.operands[1], phase: 0 });
82:      } else {
83:        const right = result;
84:        if (!apply(node.operators[frame.index], frame.left, right)) {
85:          result = false;
86:          frames.pop();
87:        } else if (frame.index + 1 === node.operators.length) {
88:          result = true;
89:          frames.pop();
90:        } else {
91:          frame.left = right;
92:          frame.index += 1;
93:          frames.push({ node: node.operands[frame.index + 1], phase: 0 });
94:        }
95:      }
96:    } else if (node.type === 'call') {
97:      if (frame.phase === 0) {
98:        frame.phase = 1;
99:        frame.index = 0;
100:        frames.push({ node: node.args[0], phase: 0 });
101:      } else {
102:        const value = Number(result);
103:        if (frame.index === 0) frame.value = value;
104:        else if (node.name === 'min') frame.value = Math.min(frame.value, value);
105:        else frame.value = Math.max(frame.value, value);
106:        frame.index += 1;
107:        if (frame.index === node.args.length) {
108:          result = node.name === 'abs' ? Math.abs(frame.value) : frame.value;
109:          frames.pop();
110:        } else {
111:          frames.push({ node: node.args[frame.index], phase: 0 });
112:        }
113:      }
114:    } else {
115:      throw new Error('Invalid AST node');
116:    }
117:  }
118:  return result;
119:}
