1:'use strict';
2:
3:const { ExprError } = require('./errors');
4:
5:/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
6:function parse(tokens) {
7:  let position = 0;
8:  const current = () => tokens[position];
9:  const take = () => tokens[position++];
10:  const is = value => current().value === value;
11:  const expect = value => {
12:    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
13:    return take();
14:  };
15:  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });
16:
17:  function comparison() {
18:    let left = sum();
19:    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
20:      const operator = take();
21:      left = binary(operator, left, sum());
22:    }
23:    return left;
24:  }
25:
26:  function sum() {
27:    let left = product();
28:    while (is('+') || is('-')) {
29:      const operator = take();
30:      left = binary(operator, left, product());
31:    }
32:    return left;
33:  }
34:
35:  function product() {
36:    let left = power();
37:    while (['*', '/', '//', '%'].includes(current().value)) {
38:      const operator = take();
39:      left = binary(operator, left, power());
40:    }
41:    return left;
42:  }
43:
44:  function unary() {
45:    if (is('+') || is('-')) {
46:      return { type: 'unary', operator: take(), operand: unary() };
47:    }
48:    return primary();
49:  }
50:
51:  function power() {
52:    let left = unary();
53:    while (is('**')) {
54:      const operator = take();
55:      left = binary(operator, left, unary());
56:    }
57:    return left;
58:  }
59:
60:  function primary() {
61:    const token = take();
62:    if (token.type === 'number') return { type: 'number', value: token.value };
63:    if (token.type === 'identifier') {
64:      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
65:      take();
66:      const args = [];
67:      if (!is(')')) {
68:        args.push(comparison());
69:        while (is(',')) {
70:          take();
71:          args.push(comparison());
72:        }
73:      }
74:      expect(')');
75:      if (!['min', 'max', 'abs'].includes(token.value)) {
76:        throw new ExprError('Unknown function', token.column);
77:      }
78:      if (!args.length || (token.value === 'abs' && args.length !== 1)) {
79:        throw new ExprError('Wrong argument count', token.column);
80:      }
81:      return { type: 'call', name: token.value, args };
82:    }
83:    if (token.value === '(') {
84:      const expression = comparison();
85:      expect(')');
86:      return expression;
87:    }
88:    throw new ExprError('Expected an expression', token.column);
89:  }
90:
91:  const expression = comparison();
92:  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
93:  return expression;
94:}
95:
96:module.exports = { parse };

