const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });
  const comparisonOperators = ['<', '<=', '>', '>=', '==', '!='];

  function comparison() {
    const first = sum();
    if (!comparisonOperators.includes(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (comparisonOperators.includes(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /** Collect signs iteratively so long sign runs do not recurse per sign. */
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let operand = power();
    for (let index = signs.length - 1; index >= 0; index -= 1) {
      operand = { type: 'unary', operator: signs[index], operand };
    }
    return operand;
  }

  function power() {
    const base = primary();
    if (!is('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      take();
      const args = [];
      if (!is(')')) {
        args.push(comparison());
        while (is(',')) {
          take();
          args.push(comparison());
        }
      }
      expect(')');
      if (!['min', 'max', 'abs'].includes(token.value)) {
        throw new ExprError('Unknown function', token.column);
      }
      if (!args.length || (token.value === 'abs' && args.length !== 1)) {
        throw new ExprError('Wrong argument count', token.column);
      }
      return { type: 'call', name: token.value, args };
    }
    if (token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

